    // and no stray personal data from URLs lands in the CRM.
    landing_page: landing ? (landing.origin + landing.pathname).slice(0, MAX_HISTORY_URL_LENGTH) : null,
    referrer_host: referrer ? stripWww(referrer.host) : null
