  'ft_utm_source',
  'ft_utm_medium',
  'ft_utm_campaign',
  'ft_converting_asset',
  'ft_timestamp',
  'lt_utm_source',
  'lt_utm_medium',
  'lt_utm_campaign',
  'lt_timestamp',
  'latest_converting_asset',
  'utm_touchpoint_history'
